function extractList(response, keys) {
  let value = response?.data ?? response?.body ?? response;
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [];
  for (const key of keys) {
    if (Array.isArray(value[key])) return value[key];
  }
  if (value.data && typeof value.data === 'object') {
    if (Array.isArray(value.data)) return value.data;
    for (const key of keys) {
      if (Array.isArray(value.data[key])) return value.data[key];
    }
  }
  return [];
}

const strategies = extractList($('03 - Get Strategies').first().json, ['strategies', 'items', 'results']);
const opportunities = extractList($('04 - Get Opportunities').first().json, ['opportunities', 'items', 'results']);
const risks = extractList($('05 - Get Risks').first().json, ['risks', 'items', 'results']);

const latestStrategies = strategies.slice(-20);
const selectedOpportunities = opportunities.slice(0, 30);
const selectedRisks = risks.slice(0, 30);
const analyzedAt = new Date().toISOString();
const hasInputData = latestStrategies.length > 0 || selectedOpportunities.length > 0 || selectedRisks.length > 0;

const prompt = `Bạn là chuyên gia tổng hợp báo cáo điều hành về chiến lược cạnh tranh. Hãy tổng hợp dữ liệu được cung cấp thành báo cáo bằng tiếng Việt.

QUY TẮC:
- Chỉ sử dụng thông tin có trong dữ liệu đầu vào, không tự bịa số liệu hoặc sự kiện.
- Phân biệt dữ kiện đã có và nhận định suy luận.
- Nêu rõ dữ liệu thiếu, mâu thuẫn hoặc chưa đủ để kết luận.
- Tổng hợp chiến lược, cơ hội và rủi ro thành một báo cáo thống nhất.
- Không khẳng định kết quả tương lai chắc chắn xảy ra.
- Trả về duy nhất JSON hợp lệ, không có Markdown.

CẤU TRÚC JSON:
{
  "report_title": "Tiêu đề báo cáo",
  "executive_summary": "Tóm tắt điều hành",
  "key_findings": ["Phát hiện chính"],
  "opportunities": ["Cơ hội đáng chú ý"],
  "risks": ["Rủi ro đáng chú ý"],
  "strategic_recommendations": ["Khuyến nghị cụ thể"],
  "limitations": ["Hạn chế dữ liệu"]
}

CHIẾN LƯỢC (${latestStrategies.length} bản ghi):
${JSON.stringify(latestStrategies)}

CƠ HỘI (${selectedOpportunities.length} bản ghi):
${JSON.stringify(selectedOpportunities)}

RỦI RO (${selectedRisks.length} bản ghi):
${JSON.stringify(selectedRisks)}

Thời điểm tổng hợp: ${analyzedAt}`;

return [{ json: { analyzed_at: analyzedAt, strategies: latestStrategies, opportunities: selectedOpportunities, risks: selectedRisks, source_counts: { strategies: latestStrategies.length, opportunities: selectedOpportunities.length, risks: selectedRisks.length }, has_input_data: hasInputData, prompt } }];

const result = $input.first().json;
const raw = result.content ?? result.text ?? result.response ?? result.output ?? result.message?.content ?? result.choices?.[0]?.message?.content;
if (typeof raw !== 'string' || !raw.trim()) {
  return [{ json: { parse_ok: false, parse_error: 'AI không trả về nội dung văn bản hợp lệ.', raw_response: result } }];
}
try {
  const clean = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('Không tìm thấy JSON trong phản hồi AI.');
  const parsed = JSON.parse(clean.slice(start, end + 1));
  return [{ json: { ...parsed, parse_ok: true } }];
} catch (error) {
  return [{ json: { parse_ok: false, parse_error: error.message, raw_response: raw } }];
}

return $input.all().map(item => {
  const d = item.json;
  const errors = [];
  if (d.parse_ok !== true) errors.push(d.parse_error || 'Không phân tích được JSON AI.');
  for (const field of ['report_title', 'executive_summary']) {
    if (typeof d[field] !== 'string' || !d[field].trim()) errors.push(`Thiếu hoặc sai kiểu dữ liệu: ${field}.`);
  }
  for (const field of ['key_findings', 'opportunities', 'risks', 'strategic_recommendations', 'limitations']) {
    if (!Array.isArray(d[field]) || !d[field].every(value => typeof value === 'string')) errors.push(`${field} phải là mảng chuỗi.`);
  }
  if (Array.isArray(d.strategic_recommendations) && d.strategic_recommendations.length < 2) errors.push('Cần ít nhất 2 khuyến nghị chiến lược.');
  return { json: { ...d, is_valid: errors.length === 0, validation_errors: errors } };
});

const report = $('10 - Validate Report Content').first().json;
const source = $('06 - Normalize Data and Prepare Report').first().json;
return [{ json: { report_title: report.report_title, executive_summary: report.executive_summary, key_findings: report.key_findings, opportunities: report.opportunities, risks: report.risks, strategic_recommendations: report.strategic_recommendations, limitations: report.limitations, generated_at: source.analyzed_at, source_counts: source.source_counts, report_valid: report.is_valid } }];
